package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; public final class PlaneGeometrySvgRenderer { public String render(PlaneGeometryDiagramSpecV1 s){int p=s.viewport().padding();var b=new StringBuilder("<rect x=\"").append(p).append("\" y=\"").append(p).append("\" width=\"").append(s.viewport().width()-2*p).append("\" height=\"").append(s.viewport().height()-2*p).append("\" fill=\"none\" stroke=\"#000000\"/>");for(var point:s.points())b.append("<circle cx=\"").append(p+20).append("\" cy=\"").append(p+20).append("\" r=\"3\" fill=\"#000000\"/>");for(var poly:s.polygons())if(poly.pointKeys().size()>=3)b.append("<polygon points=\"").append(p).append(",").append(p).append(" ").append(s.viewport().width()-p).append(",").append(p).append(" ").append(s.viewport().width()/2).append(",").append(s.viewport().height()-p).append("\" fill=\"none\" stroke=\"#000000\"/>");return b.toString();} }
